-- ============================================================
-- ASOP base seed data - generated (hierarchy-based leaf counts)
-- Крым = 0103 (Республика Крым), carrier 01403 (ГУП «Крымавтотранс»)
-- Идемпотентный: ON CONFLICT DO NOTHING на каждой строке
--
-- Использование:
--   docker compose -f infrastructure/docker/docker-compose.yml exec -T postgres
--     psql -U asop -d asop < infrastructure/docker/seed-data.sql
--
-- Counts кратко (region ~50 -> leaf делим на 2 в иерархии):
--   regions=3, territories=12, organizers=3, organizer_territories=12,
--   fare_zones=12, transport_stops=120, services=12, benefits=6, benefit_steps=25,
--   cards_distributors=6, contracts=12, vehicles=25,
--   routes=50, contract_routes=50, paths=100, path_stops=1000, schedule=50,
--   users=30, user_roles=50, user_carriers=25, user_regions=25,
--   cards=10, card_mifares=10, card_banks=4, card_tariffs=10, blacklists=3,
--   user_benefits=25, tids=10, path_services=50, path_discounts=50,
--   path_benefits=50, tariff_rates=50, vehicle_types=3, vehicle_models=6,
--   card_types=6, tariff_types=6, session_types=3, event_types=3, transaction_types=3,
--   transaction_results=3
-- ============================================================

-- 1. Regions (3 — Москва / СПб / Крым)
ON CONFLICT (REGION_ID) DO NOTHING;

-- 2. Territories (12 — по 4 на регион)
ON CONFLICT (TERRITORY_ID) DO NOTHING;

-- 3. Organizers (3 — Москва / СПб / Крым)
ON CONFLICT (ORGANIZER_ID) DO NOTHING;

-- 4. Organizer Territories (12 — каждый organizer привязан к 4 территориям своего региона)
ON CONFLICT (ORGANIZER_ID, TERRITORY_ID) DO NOTHING;

-- 5. Card Types (6)
ON CONFLICT (CARD_TYPE_ID) DO NOTHING;

-- 6. Tariff Types (6)
ON CONFLICT (TARIFF_TYPE_ID) DO NOTHING;

-- 7. Session Types (3)
ON CONFLICT (SESSION_TYPE_ID) DO NOTHING;

-- 8. Event Types (CHAR(4) PK)
ON CONFLICT (EVENT_TYPE) DO NOTHING;

-- 9. Transaction Types (3)
ON CONFLICT (TRANSACTION_TYPE_ID) DO NOTHING;

-- 10. Transaction Results (3)
ON CONFLICT (TRANSACTION_RESULT_ID) DO NOTHING;

-- 11. Vehicle Types (3)
ON CONFLICT (VEHICLE_TYPE_ID) DO NOTHING;

-- 12. Vehicle Models (6)
ON CONFLICT (VEHICLE_MODEL_ID) DO NOTHING;

-- 13. Carriers (3 — основные перевозчики)
ON CONFLICT (CARRIER_ID) DO NOTHING;

-- 14. Cards Distributors (6)
ON CONFLICT (CARDS_DISTRIBUTOR_ID) DO NOTHING;

-- 15. Contracts (12 — типа carrier/distributor shared)
ON CONFLICT (CONTRACT_ID) DO NOTHING;

-- 16. Vehicles (25 — 9 Москва, 8 СПб, 8 Крым)
ON CONFLICT (VEHICLE_ID) DO NOTHING;

-- 17. Fare Zones (12 — 4 на регион)
ON CONFLICT (ZONE_ID) DO NOTHING;

-- 18. Transport Stops (120 — по 40 в каждом регионе, по 10 на fare_zone)
ON CONFLICT (STOP_ID) DO NOTHING;

-- 19. Services (12 — по 4 на регион)
ON CONFLICT (SERVICE_ID) DO NOTHING;

-- 20. Benefits (6 — по 2 на регион)
ON CONFLICT (BENEFIT_ID) DO NOTHING;

-- 21. Benefit Steps (25)

ON CONFLICT (STEP_ID) DO NOTHING;

-- 22. Routes (50 — 17 Москва, 16 СПб, 17 Крым)

ON CONFLICT (ROUTE_ID) DO NOTHING;

-- 23. Contract Routes (~50)

ON CONFLICT (CONTRACT_ID, ROUTE_ID) DO NOTHING;

-- 24. Paths (100 — каждый маршрут имеет «туда» и «обратный»)

ON CONFLICT (PATH_ID) DO NOTHING;

-- 25. Path Transport Stops (1000 — 10 остановок на каждый из 100 путей)

ON CONFLICT (PATH_STOP_ID) DO NOTHING;

-- 26. Schedule (50 — одна запись на маршрут)

ON CONFLICT (SCHEDULE_ID) DO NOTHING;

-- 27. Users (30 — по 10 на регион)

ON CONFLICT (USER_ID) DO NOTHING;

-- 28. User Roles (~50 — каждый user имеет 1-2 роли)

ON CONFLICT (USER_ID, ROLE_ID) DO NOTHING;

-- 29. User Carriers (25)

ON CONFLICT (USER_ID, CARRIER_ID) DO NOTHING;

-- 30. User Regions (25)

ON CONFLICT (USER_ID, REGION_ID) DO NOTHING;

-- 31. Cards (10 — по региону 4/3/3)

ON CONFLICT (CARD_ID) DO NOTHING;

-- 32. Card Mifares (10)

ON CONFLICT (CARD_ID) DO NOTHING;

-- 33. Card Banks (4 — половина 10 карт как банковские)

ON CONFLICT (CARD_ID) DO NOTHING;

-- 34. Card Tariffs (10)

ON CONFLICT (CARD_TARIFF_ID) DO NOTHING;

-- 35. Blacklists (3)

ON CONFLICT (CARD_ID) DO NOTHING;

-- 36. User Benefits (25)

ON CONFLICT (ASSIGNMENT_ID) DO NOTHING;

-- 37. TIDs (10 — по carrier-pool)

ON CONFLICT (TID_ID) DO NOTHING;

-- 38. Path Services (50)

ON CONFLICT (PATH_SERVICE_ID) DO NOTHING;

-- 39. Path Discounts (50)

ON CONFLICT (PATH_DISCOUNT_ID) DO NOTHING;

-- 40. Path Benefits (50)

ON CONFLICT (PATH_BENEFIT_ID) DO NOTHING;

-- 41. Tariff Rates (50)

ON CONFLICT (TARIFF_RATE_ID) DO NOTHING;

